INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 20, 'theory', 'Networks in the Cloud and Containers: Docker, VPC, and Kubernetes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 0, 'How does a public VPC subnet differ from a private one?', '["The size of the address range", "A public subnet''s default route leads to an Internet Gateway; a private one''s does not (or leads to a NAT gateway)", "A public one is always faster", "A private one does not support IPv4"]', 1, 'It is all determined by the subnets'' route tables.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 1, 'What does the security group rule "DB: port 3306 from the application group" do?', '["Opens the database to the whole internet", "Blocks outgoing connections", "Encrypts traffic", "Allows inbound traffic on 3306 only from machines in the application group; everything else is closed"]', 3, 'The rule''s source is a group, not addresses, which is convenient when the number of servers changes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 2, 'What happens when you publish a container port with "-p 8080:80"?', '["A DNAT rule is added on the node from port 8080 to the container''s address and port 80", "The container switches to host mode", "The container gets a public IP", "Isolation is turned off"]', 0, 'Docker adds netfilter rules: DNAT for incoming traffic and MASQUERADE for outgoing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 3, 'Why does Kubernetes need a Service if every pod has its own address?', '["Pod addresses are permanent, so a Service is not needed", "A Service encrypts traffic", "Pods are short-lived and change addresses; a Service provides a permanent address and balancing across ready pods", "A Service replaces DNS"]', 2, 'kube-proxy spreads requests across the pods that have passed the readiness check.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 20, 4, 'What does a NetworkPolicy provide?', '["Increases network speed", "Assigns addresses to pods", "Signs images", "Restricts which pods may talk to each other"]', 3, 'Without policies all pods see all pods; a policy leaves access only to the ones that need it.');
